import sqlite3
con = sqlite3.connect(":memory:")
con.executescript("""
CREATE TABLE customers(id INTEGER PRIMARY KEY, name TEXT);
INSERT INTO customers VALUES (1,'Sharma Electricals'),(2,'Gupta Traders'),(3,'Verma Cables');
CREATE TABLE orders(id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER);
INSERT INTO orders VALUES (1,1,50000),(2,1,30000),(3,2,75000);
""")
q = """SELECT c.name, COALESCE(SUM(o.amount), 0)
FROM customers c LEFT JOIN orders o ON o.customer_id = c.id
GROUP BY c.id ORDER BY c.name"""
for name, total in con.execute(q):
    print(name, total)
